using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class LabLightCapture{
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Lighting/"));
 static void Shot(string n,Vector3 pos,Vector3 target,float fov){var go=new GameObject("LightingReview_Temporary");var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.02f;c.farClipPlane=180;c.fieldOfView=fov;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.027f,.037f,.05f);c.GetUniversalAdditionalCameraData().renderPostProcessing=false;c.allowMSAA=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Before()=>Run("Before");public static object After()=>Run("After");
 static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var hidden=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToDictionary(r=>r,r=>r.enabled);try{foreach(var r in hidden.Keys)r.enabled=false;foreach(var t in room.Cast<Transform>().Where(t=>t.name.StartsWith("S1_WallTaskLight"))){Shot(prefix+"_"+t.name,t.TransformPoint(new Vector3(1,-1.4f,2.9f)),t.TransformPoint(new Vector3(0,-.08f,.82f)),60);}Shot(prefix+"_Room",room.position+new Vector3(5.8f,1.65f,0),room.position+new Vector3(-3.5f,2.0f,0),82);Shot(prefix+"_WorkArea",room.position+new Vector3(3.3f,1.65f,4.4f),room.position+new Vector3(5.6f,1.4f,6.0f),74);Shot(prefix+"_PodCeiling",room.position+new Vector3(1.8f,2.0f,.4f),room.position+Vector3.up*5.9f,66);Shot(prefix+"_Portal",room.position+new Vector3(1.5f,1.65f,0),new Vector3(-5.840165f,-79.8f,-9.141265f),70);}finally{foreach(var kv in hidden)kv.Key.enabled=kv.Value;EditorSceneManager.OpenScene(s.path);}return new{prefix,images=8,output=O};}
}
